 let pl=allPlayers().filter(p=>p.played).length,plus=pl?' (plus Week '+META.next_week+' games as they finish)':'';if($('homeWkPlus'))$('homeWkPlus').textContent=plus;if($('wkPlus'))$('wkPlus').textContent=plus;
