 let nAll=arr.length,needCards=window.innerWidth<=800;arr=arr.slice(0,rkLim);let rows=[];(needCards?[]:arr).forEach((p,i)=>{let oppT=p.played?`vs ${p.opp} • ✓ ${resTxt(p.played)}`:`vs ${p.opp}`,sub=`${tlogo(p.team,'sm')}${p.team} ${p.pos} • ${oppT}${p.sub?' • backup':''}`,pr=p.out?'OUT':p.proj?p.proj.pts.toFixed(1):'—',mn=p.mania==null?'<td class="muted">—</td>':`<td class="grade ${grade(p.mania)}">${p.mania}</td>`,wk=p.played&&p.played.grade!=null?`<td class="grade ${grade(p.played.grade)}">${Number(p.played.grade).toFixed(1)}<span class="pdone">✓</span></td>`:p.start==null||p.out?`<td class="muted">${p.out?'OUT':'—'}</td>`:`<td class="grade ${grade(p.start)}">${p.start}</td>`;
  rows.push(`<tr class="pjr"><td class="rn">${i+1}</td><td class="pjp"><div class="nmw">${thumb(p)}<div class="nmt2"><span class="playerlink" data-id="${p.id}">${p.name}</span>${injChip(p)}<div class="pjs">${sub}${bIcons(p.bl||[])}</div></div></div></td>${mn}${wk}<td class="pjv">${pr}</td><td class="pjv">${ptsCell(p)}</td><td class="dOnly muted">${p.proj&&!p.out?p.proj.lo.toFixed(0)+'–'+p.proj.hi.toFixed(0):'—'}</td></tr>`)});
