 if(nAll>arr.length){let mb='<button type="button" class="rkMore">Show more ('+(nAll-arr.length)+' left)</button>';if(needCards)$('rankCards').insertAdjacentHTML('beforeend',mb);else $('rankBody').insertAdjacentHTML('beforeend','<tr class="rkMoreR"><td colspan="'+CL.length+'">'+mb+'</td></tr>')}
