function percentile(pos,key,v){let a=(REFS[pos]||{})[key]||[];if(!a.length)return 0;let lo=0,hi=a.length;while(lo<hi){let m=(lo+hi)>>1;if(a[m]<=v+1e-5)lo=m+1;else hi=m}return Math.min(100,lo/a.length*100)}function avg(a,k,w=true){let den=0,num=0;a.forEach(x=>{let z=w?(x.weight||1):1;num+=Number(x[k]||0)*z;den+=z});return den?num/den:0}function sum(a,k){return a.reduce((s,x)=>s+Number(x[k]||0)*(x.weight||1),0)}
function customMatch(p,M){let ex=p.similar||[];if(!ex.length)return {adj:p.matchup_adj,list:[]};let scored=ex.map(x=>{let share=p.pos==='RB'?M.touch_share:M.target_share,rz=p.pos==='RB'?M.rz_carries_pg:M.rz_targets_pg;let dif=[Math.abs(M.targets_pg-x.tgt)/Math.max(3,x.tgt,1),Math.abs(M.rec_pg-x.rec)/Math.max(2,x.rec,1),Math.abs(M.snap_pct-x.snap)/35,Math.abs(share-x.share)/20,Math.abs(rz-x.rz)/2];let sim=Math.max(.15,Math.exp(-.8*dif.reduce((a,b)=>a+b,0)/dif.length));return {...x,csim:sim,delta:(x.actual/Math.max(x.normal,3)-1)*100}}).sort((a,b)=>b.csim-a.csim);let use=scored.filter(x=>x.csim>=.28),den=use.reduce((s,x)=>s+x.csim*x.csim,0);if(!den)return {adj:0,list:scored.slice(0,4)};let eff=use.reduce((s,x)=>s+x.delta*x.csim*x.csim,0)/den,maturity=Math.min(1,META.week/8),evidence=Math.min(1,use.length/6),adj=Math.max(-6,Math.min(6,eff/25*6))*maturity*(.45+.55*evidence);return {adj:p.pos==='TE'?adj*.35:adj,list:scored.slice(0,4)}}
function dfl(p){let a=p.logs.map((l,i)=>l.auto?-1:i).filter(i=>i>=0);return a.length?a:p.logs.map((_,i)=>i)}
function dflC(p){let a=p.logs.map((l,i)=>(l.auto||l.partial)?-1:i).filter(i=>i>=0);return a.length?a:dfl(p)}
function sameSet(a,b){return a.length===b.length&&a.every(x=>b.includes(x))}
function calc(p,idxs){let L=idxs.map(i=>p.logs[i]).filter(Boolean);if(!L.length)return null;let M={};M.ppr_pg=avg(L,'ppr');M.targets_pg=avg(L,'tgt');M.rec_pg=avg(L,'rec');M.rec_yards_pg=avg(L,'ry');M.carries_pg=avg(L,'car');M.rush_yards_pg=avg(L,'ruy');M.scrim_pg=M.rec_yards_pg+M.rush_yards_pg;M.td_pg=avg(L,'rtd')+avg(L,'rutd');M.snap_pct=avg(L,'snap');M.target_share=avg(L,'tshare');M.air_share=avg(L,'ashare');M.touch_share=avg(L,'touch');M.rz_targets_pg=avg(L,'rzt');M.endzone_targets_pg=avg(L,'ez');M.rz_carries_pg=avg(L,'rzc');M.gl_carries_pg=avg(L,'gl');M.yards_per_target=sum(L,'tgt')?sum(L,'ry')/sum(L,'tgt'):0;M.catch_rate=sum(L,'tgt')?sum(L,'rec')/sum(L,'tgt')*100:0;M.yards_per_carry=sum(L,'car')?sum(L,'ruy')/sum(L,'car'):0;let opp=sum(L,'car')+2*sum(L,'tgt');M.fp_per_weighted_opp=opp?sum(L,'ppr')/opp:0;let P={};Object.keys(M).forEach(k=>P[k]=percentile(p.pos,k,M[k]));let prod,op,role,hv,eff;if(p.pos==='RB'){prod=.55*P.ppr_pg+.30*P.scrim_pg+.15*P.td_pg;op=.45*P.carries_pg+.35*P.targets_pg+.20*P.rec_pg;role=.60*P.touch_share+.40*P.snap_pct;hv=.40*P.rz_carries_pg+.35*P.gl_carries_pg+.25*P.rz_targets_pg;eff=.55*P.fp_per_weighted_opp+.25*P.yards_per_carry+.20*P.catch_rate}else{prod=.55*P.ppr_pg+.30*P.rec_yards_pg+.15*P.td_pg;op=.50*P.targets_pg+.30*P.rec_pg+.20*P.target_share;role=.45*P.target_share+.30*P.air_share+.25*P.snap_pct;hv=.60*P.rz_targets_pg+.40*P.endzone_targets_pg;eff=.45*P.yards_per_target+.30*P.catch_rate+.25*P.fp_per_weighted_opp}let W=p.pos==='RB'?[.30,.30,.20,.125,.075]:[.30,.30,.225,.10,.075],raw=W[0]*prod+W[1]*op+W[2]*role+W[3]*hv+W[4]*eff,base0=45+.52*raw,base=(p.pos==='TE'&&base0<93.6)?Math.max(35,93.6-(93.6-base0)*1.5):base0,eg=L.reduce((s,x)=>s+(x.auto?1:(x.weight==null?1:x.weight)),0),conf=Math.min(1,eg/Math.max(META.week,1)),sh=(1-conf)*.12,mania=Math.max(0,Math.min(99.5,base*(1-sh)+72*sh));let recent=L.slice(-Math.min(2,L.length)),recentOpp=recent.reduce((s,x)=>s+2*x.tgt+x.car,0)/recent.length,seasonOpp=M.targets_pg*2+M.carries_pg,tr=seasonOpp?((recentOpp/seasonOpp)-1)*100:0,trend=Math.max(-2.5,Math.min(2.5,tr/20*2.5));if(L.length<2)trend*=.25;let mt=customMatch(p,M),start=Math.max(0,Math.min(100,mania+mt.adj+trend+(p.inj_adj||0)));if(p.out||p.played)start=0;if(!window.RAWC&&sameSet(idxs,dfl(p))){mania=p.mania;start=p.start}return {mania,start,M,match:mt,b:p.pos==='RB'?{'Fantasy Production':prod,'Touch Volume':op,'Backfield Control':role,'Goal-Line / Red-Zone':hv,'Per-Touch Efficiency':eff}:{'Fantasy Production':prod,'Target Volume':op,'Team Target Role':role,'Red-Zone Threat':hv,'Per-Target Efficiency':eff}}}
function barColor(v){return v>=70?'#22a45d':v>=40?'#e3a21a':'#e2505b'}function barGrade(v){return v>=70?'g90':v>=40?'g70':'g0'}function stat(v,k,pos,key,raw){let pc=key?Math.max(1,Math.min(99,Math.round(percentile(pos,key,raw)))):null;return `<div class="stat"><div class="sv">${v}</div><div class="sk">${k}</div>${pc!==null?`<div class="spc ${barGrade(pc)} lnk" data-board="stat" data-key="${key}" data-title="${k}" data-pos="${pos}" title="See everyone ranked">${ord(pc)} percentile</div>`:''}</div>`}
var roomMode='tch';
function roomVal(p,z,mode){if(p.pos!=='RB')return [z.tgt,z.ry||0];if(mode==='car')return [z.car,z.ruy||0];if(mode==='tgt')return [z.tgt,z.ry||0];return [z.car+z.tgt,(z.ruy||0)+(z.ry||0)]}
function roomTable(p){let rb=p.pos==='RB',mode=rb?roomMode:'tgt',unit={tch:'touch',car:'carry',tgt:'target'}[mode],shK={tch:'tch',car:'csh',tgt:'tsh'}[mode],shL={tch:'touches',car:'carries',tgt:'targets'}[mode],weeks=[...new Set(p.room.flatMap(x=>x.weekly.map(w=>w.w)))].sort((a,b)=>a-b),sv=(z,k)=>z[k]==null?(k==='tch'?z.share:null):z[k];
 return `<div class="tablewrap"><table class="roomtable"><thead><tr><th>Player</th>${weeks.map(w=>`<th>W${w}</th>`).join('')}<th>Per game</th></tr></thead><tbody>${p.room.map(x=>{let tc=0,ty=0,ss=0,sn=0,g=x.weekly.length;x.weekly.forEach(z=>{let v=roomVal(p,z,mode);tc+=v[0];ty+=v[1];ss+=+sv(z,shK)||0;sn+=+z.snap||0});return `<tr><td class="${x.id===p.id?'you':''}" data-id="${x.id}">${x.name}</td>${weeks.map(w=>{let z=x.weekly.find(q=>q.w===w);if(!z)return '<td>—</td>';let v=roomVal(p,z,mode),h=sv(z,shK);return `<td class="rmc"><b>${v[0]}</b><small>${v[1]} yds</small>${h!=null?`<small class="rmp">${Math.round(h)}% ${shL}</small>`:''}${z.snap!=null?`<small class="rmp">${z.snap}% snaps</small>`:''}</td>`}).join('')}<td class="rmc rmS">${g?`<b>${(tc/g).toFixed(1)}</b><small>${Math.round(ty/g)} yds a game${tc?' • '+(ty/tc).toFixed(1)+' per '+unit:''}</small><small class="rmp">${Math.round(ss/g)}% ${shL}</small><small class="rmp">${Math.round(sn/g)}% snaps</small>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`}
function roomHTML(p){let rb=p.pos==='RB';return `<div class="roomCtl">${rb?`<div class="roomNote"><b>Touches</b> = carries + targets. Switch to look at just carries or just targets.</div><div class="rmSeg">${[['tch','Touches'],['car','Carries only'],['tgt','Targets only']].map(([k,l])=>`<button type="button" class="rmb${roomMode===k?' on':''}" data-rm="${k}">${l}</button>`).join('')}</div>`:`<div class="roomNote">Targets and receiving yards each week, with his share of the team targets and his snap percentage.</div>`}</div><div id="roomBody">${roomTable(p)}</div><div class="explain">${rb?'Each cell is the count that week with his yards on those '+({tch:'touches',car:'carries',tgt:'targets'}[roomMode])+' plus his share of the team and his snap percentage.':'Each cell is targets that week, with receiving yards, share of team targets and snap percentage.'} Click a name to open that player.</div>`}
