var CUSTSEL=window.CUSTSEL=window.CUSTSEL||{};function customProfile(p){let idx=[...document.querySelectorAll('.gameToggle:checked')].map(x=>Number(x.dataset.i));if(idx.length)CUSTSEL[p.id]=idx;let c=calc(p,idx);if(!c){$('customLine').textContent='Select at least one game.';return}$('maniaTop').textContent=c.mania.toFixed(1);$('maniaTop').className='scorebig '+grade(c.mania);let ws=p.start!=null?p.start:c.start;$('startTop').textContent=fs(p,ws);$('olBox').innerHTML=olHTML(p,outlook(p,ws),idx);$('startTop').className='scorebig '+(p.played?grade(sval(p)):grade(ws));$('portrait').style.setProperty('--score',c.mania);$('portrait').style.setProperty('--ring',ring(c.mania));{let o=$('portrait').querySelector('.rsv');if(o)o.outerHTML=ringSvg(c.mania)}$('profileBars').innerHTML=bucketRows(c.b,p);wireInfo();$('usagePanel').innerHTML=usageHTML(p,c);wireUsage();$('matchPanel').innerHTML=matchupHTML(p,c);$('customLine').innerHTML=`Official <b>${p.mania}</b> → Mania Rating <b class="${grade(c.mania)}">${fmt(c.mania)}</b> • Week ${META.next_week} score stays tied to the projection • ${idx.length} game${idx.length===1?'':'s'} used. The Rankings tab always uses the full season.`;$('allGames').checked=idx.length===p.logs.length;try{profRefresh(p,c)}catch(e){}}
var TCOL={ARI:'#97233f',ATL:'#a71930',BAL:'#4b2fa8',BUF:'#1d4fb8',CAR:'#0085ca',CHI:'#1f3a6e',CIN:'#e8540c',CLE:'#6b3a12',DAL:'#2a55b8',DEN:'#e8540c',DET:'#0076b6',GB:'#2b5a4c',HOU:'#1a3a5c',IND:'#2a5fb0',JAX:'#12808f',KC:'#d41b3a',LV:'#3a3f47',LAC:'#0080c6',LAR:'#2a55b8',LA:'#2a55b8',MIA:'#0aa0a8',MIN:'#5a2f96',NE:'#1c3b6e',NO:'#a08a4a',NYG:'#1c3a8f',NYJ:'#17714f',PHI:'#0a6b73',PIT:'#d9a300',SF:'#b01818',SEA:'#1c4a7a',TB:'#d50a0a',TEN:'#2a5a9c',WAS:'#7a1f1f',WSH:'#7a1f1f'};
function pvBars(rows){return rows.map(([l,t,w])=>`<div class="pvb"><span>${l}</span><div class="pvt">${w!=null?`<i style="width:${Math.max(3,Math.min(100,w))}%"></i>`:''}</div><b>${t}</b></div>`).join('')}
function pvRow(l,t,cl){return `<div class="pvr"><span>${l}</span><b class="${cl||''}">${t}</b></div>`}
function profPrev(p,k,c){if(p.pos==='QB'&&/^q(num|adv|lad|b|story|cast)$/.test(k))return qbPrev(p,k);let m=p.m||{},n=x=>x==null||x===''?null:Number(x),f=(x,d)=>x==null?'—':Number(x).toFixed(d==null?1:d);
 if(k==='mania'){let rows=[...document.querySelectorAll('#profileBars .barrow')];return '<div class="pmb">'+rows.map(r=>{let l=(r.querySelector('.lblBtn')||{}).textContent||'',lb=l.replace('ⓘ','').trim(),fl=r.querySelector('.fill'),nm=r.querySelector('.pctNum'),cl=nm?nm.className.replace(/\blnk\b/,'').replace('pctNum','pctNum pmN'):'pctNum pmN',sv=nm?nm.style.getPropertyValue('--s'):'0';return `<div class="pmr"><span>${lb}</span><b class="${cl}" style="--s:${sv}">${nm?nm.textContent:''}</b><div class="track"><div class="fill" style="width:${fl?fl.style.width:'0'};background:${fl?fl.style.background:''}"></div></div></div>`}).join('')+'</div>'}
 if(k==='proj'){let b=document.querySelector('#profileBody .projBox');if(!b)return '';let g=q=>{let e=b.querySelector(q);return e?e.outerHTML:''};let rg=[...b.querySelectorAll('.projRng span')];return `<div class="pvbig">${(b.querySelector('.projNum')||{}).textContent||''}</div><div class="pvs">projected points</div>${g('.projBar')}<div class="pvs pvrng">${rg[0]?rg[0].textContent:''} · ${rg[2]?rg[2].textContent:''}</div>${g('.projFx')}`}
 if(k==='match'){if(p.opp==='BYE')return '<div class="pvbig">Bye week</div><div class="pvs">No matchup to adjust for.</div>';if(p.opp==='TBD'||!p.opp)return '<div class="pvbig">TBD</div><div class="pvs">Opponent not set yet.</div>';
  let adj=((c?c.match.adj:p.matchup_adj)||0),sg=adj>=0?'+':'',rows=defenseVs(p.pos).slice().sort((a,b)=>b.pg-a.pg),ix=rows.findIndex(x=>x.team===p.opp),tag=adj>=1?['Good matchup','up']:adj<=-1?['Tough matchup','dn']:['Neutral matchup',''];
  return `<div class="pvbig">vs ${p.opp}</div><div class="pvs ${tag[1]}">${tag[0]}</div>${pvRow('Adjustment',sg+adj.toFixed(1)+' pts',adj>=0?'up':'dn')}${ix>=0?pvRow('Allows to '+p.pos+'s',(ix+1)+(['st','nd','rd'][ix]&&ix<3?['st','nd','rd'][ix]:'th')+' most'):''}${pvRow('Week',META.next_week)}`}
 if(k==='usage'){let rb=p.pos==='RB';return pvBars(rb?[['Snaps',f(m.snap,0)+'%',n(m.snap)],['Touch share',f(m.touch,0)+'%',n(m.touch)],['Carries/G',f(m.car),n(m.car)*4],['PPR/G',f(m.ppr),n(m.ppr)*3.5]]:[['Snaps',f(m.snap,0)+'%',n(m.snap)],['Target share',f(m.tshare,0)+'%',n(m.tshare)*2.5],['Targets/G',f(m.tgt),n(m.tgt)*9],['PPR/G',f(m.ppr),n(m.ppr)*4]])}
 if(k==='room'){let sh=x=>x.pos==='RB'?(x.m||{}).touch:(x.m||{}).tshare,L=DB.filter(x=>x.team===p.team&&x.pos===p.pos&&sh(x)!=null).sort((a,b)=>sh(b)-sh(a)).slice(0,5);return L.map(x=>`<div class="pvr${x.id===p.id?' me':''}"><span data-popen="${x.id}">${trAb(x.name)}</span><b>${f(sh(x),0)}%</b></div>`).join('')+`<div class="pvs">${p.pos==='RB'?'Share of touches':'Share of targets'}</div>`}
 if(k==='sched'){let row=schedule(p.pos,'all').find(x=>x.team===p.team);if(!row||!row.games.length)return '<div class="pvs">No games left.</div>';return '<div class="pvch">'+row.games.slice(0,9).map(g=>g.opp?`<span class="sch ${edgeClass(g.vs)}">${g.w} ${g.opp}</span>`:`<span class="sch muted">${g.w} bye</span>`).join('')+'</div>'+`<div class="pvs">Green easier, red tougher</div>`}
 if(k==='log'){let L=(p.logs||[]).slice(-6),mx=Math.max(1,...L.map(l=>+l.ppr||0));return `<div class="pvbars">${L.map(l=>`<div><i style="height:${Math.max(6,(+l.ppr||0)/mx*46)}px;background:${barColor(Math.min(99,(+l.ppr||0)*4))}"></i><em>${l.ppr}</em><small>W${l.w}</small></div>`).join('')}</div>`+pvRow('Games',(p.logs||[]).length)+pvRow('PPR/G',f(m.ppr))}
 if(k==='games'){let n0=document.querySelectorAll('.gameToggle:checked').length||(p.logs||[]).filter(l=>!l.auto).length;return `<div class="pvbig">${n0} of ${(p.logs||[]).length}</div><div class="pvs">games counted. Open to untick any game and everything recalculates.</div>`}
 if(k==='qb'){return '<div class="pvs">Quarterbacks are graded against quarterbacks on the same 0 to 100 scale. Open for the full method.</div>'}
 return ''}
function profRefresh(p,c){document.querySelectorAll('#profileBody .ptile').forEach(t=>{let k=t.dataset.k;if(k==='match'||k==='usage'||k==='games'||k==='mania'||k==='proj'){let b=t.querySelector('.pbody');if(b)b.innerHTML=profPrev(p,k,c)}})}
