  room=by(/room/i),sched=by(/Schedule ahead/i),log=by(/^Game log/i),match=$('matchPanel'),usage=$('usagePanel'),qbx=g2?[...g2.querySelectorAll('.colR > .panel')][0]:null;
 let wrap=document.createElement('div');wrap.className='ptiles';
 const mk=(k,title,el)=>{if(!el)return;let t=document.createElement('div');t.className='ptile';t.dataset.k=k;t.innerHTML=`<button type="button" class="ptx" aria-label="Expand or close ${title}"></button><div class="pprev"><div class="pk">${title}</div><div class="pbody">${profPrev(p,k)}</div></div><div class="pfull"></div>`;t.querySelector('.pfull').appendChild(el);wrap.appendChild(t)};
 mk('mania','Mania breakdown',mania);let pjb=B.querySelector(':scope > .projBox');if(pjb)mk('proj',pjb.querySelector('.ph')?pjb.querySelector('.ph').textContent:'Projection',pjb);
 mk('match','Week '+META.next_week+' matchup',match&&match.parentNode?match:null);mk('usage','Usage',usage);mk('room',p.team+' '+p.pos+' room',room);mk('sched','Schedule ahead',sched);if(p.pos==='QB'){mk('qstory','The real story',by(/^The real story/i));mk('qcast','The team around him',by(/^The team around him/i));mk('qnum','By the numbers',by(/^By the numbers/i));mk('qadv','Advanced passing',by(/^Advanced passing/i));mk('qb','How a QB is rated',qbx);mk('qlad','Where he sits',by(/^Where he sits/i))}mk('log','Game log',log);if(games){let gw=document.createElement('div');gw.className='pgTop';gw.appendChild(games);let hd=games.firstElementChild;if(hd){let hb=document.createElement('button');hb.type='button';hb.className='pgHide';hb.textContent='Hide ▴';hd.appendChild(hb)}let mn=document.createElement('button');mn.type='button';mn.className='pgMin';gw.appendChild(mn);const cnt=()=>{let a=gw.querySelectorAll('.gameToggleChip,.qbChip'),c=gw.querySelectorAll('.gameToggleChip:checked,.qbChip:checked');return c.length+' of '+a.length};gw.addEventListener('change',e=>{if(e.target.matches('input'))gw.classList.add('edited')});gw.addEventListener('click',e=>{if(e.target.closest('#resetGames,#qbReset'))gw.classList.add('edited');if(e.target.closest('.pgHide')){mn.innerHTML='<span>Games counted <b>'+cnt()+'</b></span><i>Edit</i>';gw.classList.add('min')}else if(e.target.closest('.pgMin')){gw.classList.remove('min')}});const sync=()=>{mn.innerHTML='<span>Games counted <b>'+cnt()+'</b></span><i>Edit</i>'};sync();gw.classList.add('min');gw.addEventListener('change',()=>setTimeout(sync,0));gw.addEventListener('click',e=>{if(e.target.closest('#resetGames,#qbReset'))setTimeout(sync,0)});hero.insertAdjacentElement('afterend',gw)}
 (g2||B.lastElementChild).insertAdjacentElement(g2?'beforebegin':'afterend',wrap);if(g2)g2.remove();
