function trAttach(root,sel,pick){let inp=root.querySelector(sel+' input'),dd=root.querySelector(sel+' .dd');if(!inp)return;inp.oninput=()=>{let s=inp.value.toLowerCase().trim();if(!s){dd.style.display='none';return}let c=trCtx().V,m=Object.values(c).map(v=>v.p).filter(p=>p.name.toLowerCase().includes(s)).sort((a,b)=>c[b.id].raw-c[a.id].raw).slice(0,8);
 dd.innerHTML=m.map(p=>`<div class="ddi" data-id="${p.id}"><div><span class="ddiName">${p.name}</span><span class="ddiMeta">${p.team} • ${p.pos}</span></div><span class="ddiRate">${trN(c[p.id].val)}</span></div>`).join('')||'<div class="ddi muted">No match</div>';dd.style.display='block';dd.querySelectorAll('.ddi[data-id]').forEach(x=>x.onclick=()=>{dd.style.display='none';inp.value='';pick(x.dataset.id)})}}
function trAdd(list,id){if(!list.includes(id))list.push(id)}
function trSettings(){let n=TR.n,s=TR.st,steps=[['Teams in league','n',6,20],['RB','RB',0,4],['WR','WR',0,4],['TE','TE',0,3],[TR.sf?'Superflex (QB/RB/WR/TE)':'Flex (RB/WR/TE)','FLEX',TR.sf?1:0,3]];
 return `<details class="tset trSetD"${TRopen.set?' open':''}><summary><span>League</span><i>${n} teams • PPR • ${TR.sf?'Superflex':'1 QB'} • ${TR.hz==='now'?'win now':TR.hz==='play'?'playoffs':'full season'} • ${s.RB}RB ${s.WR}WR ${s.TE}TE ${TR.sf?'1 SUPERFLEX'+(s.FLEX>1?' '+(s.FLEX-1)+'FLEX':''):s.FLEX+'FLEX'}</i></summary><div class="tsetB"><div class="tpre"><button type="button" class="tsb trsf${TR.sf?'':' on'}" data-v="0">1 QB</button><button type="button" class="tsb trsf${TR.sf?' on':''}" data-v="1">Superflex</button></div><div class="tsec" style="margin:6px 2px">What matters most</div><div class="tpre">${[['now','Next 4 weeks'],['ros','Whole season'],['play','Playoffs (Wk 14-17)']].map(([k,l])=>`<button type="button" class="tsb trhz${TR.hz===k?' on':''}" data-v="${k}">${l}</button>`).join('')}</div><div class="tsteps">${steps.map(([l,k,lo,hi])=>`<div class="tst"><span>${l}</span><div><button type="button" class="tstb trst" data-k="${k}" data-d="-1" data-lo="${lo}" data-hi="${hi}">−</button><b>${k==='n'?n:s[k]}</b><button type="button" class="tstb trst" data-k="${k}" data-d="1" data-lo="${lo}" data-hi="${hi}">+</button></div></div>`).join('')}</div><p class="tnote" style="margin:8px 0 0">Scoring is PPR. A bigger league leaves fewer good players on waivers, so every starter is worth more. Superflex makes quarterbacks much more valuable. We assume your bench is just the players you enter.</p><details class="trsrc"><summary>How values work and sources</summary><div class="trsrcB"><p>Value is how many points a player adds over a replacement you could grab off waivers, summed over the games left, then stretched so stars are worth far more than depth. In Superflex one starting spot can be a QB, so the replacement QB is a starter-level QB instead of a free pickup, and good QBs jump up. The size of that jump (about 1.4x) is our judgment call to match the written advice below. No 2026 source publishes an exact Superflex number.</p><a href="https://www.fantasypros.com/2026/06/a-beginners-guide-to-understanding-superflex-leagues/" target="_blank" rel="noopener">FantasyPros: Understanding Superflex (Jun 2026)</a><a href="https://fantasynerds.com/news/story/2026/08/24/superflex-league-draft-strategy-prioritizing-qbs-and-navigating-value-1604506" target="_blank" rel="noopener">Fantasy Nerds: Superflex strategy (Aug 2026)</a><a href="https://www.cbssports.com/fantasy/football/news/superflex-fantasy-football-strategy-quarterbacks-drafting/" target="_blank" rel="noopener">CBS Sports: QBs in Superflex (Aug 2026)</a><a href="https://www.fantasypros.com/2026/08/fantasy-football-strategy-how-to-draft-quarterbacks-2026/" target="_blank" rel="noopener">FantasyPros: How to draft QBs (Aug 2026)</a><a href="https://www.rotostreetjournal.com/2026/10/13/2026-fantasy-football-week-6-trade-value-chart/" target="_blank" rel="noopener">Roto Street Journal: Week 6 trade value chart (Oct 2026, 1 QB)</a></div></details></div></details>`}
function trSearchBox(id,ph){return `<div class="search trS" id="${id}"><input placeholder="${ph}" autocomplete="off"><div class="dd"></div></div>`}
function trSlotLab(x){return x==='SFLEX'?'SFX':x==='FLEX'?'FLX':x}
function trLineHTMLm(L,mark,map){TRCVmap=map;let h=trLineHTML(L,mark);TRCVmap=null;return h}
function trLineHTML(L,mark){return L.st.map(x=>x.v?trRow(x.v.p.id,'',mark&&mark.has(x.v.p.id)?'<b class="trNew">NEW</b>':'').replace('<div class="trNm">',`<div class="trNm"><span class="trSlot">${trSlotLab(x.slot)}</span>`):`<div class="trRow"><span class="trTh"></span><div class="trNm"><span class="trSlot">${trSlotLab(x.slot)}</span><b>Empty slot</b><small>Counted as a free agent (${trN(x.ppg)} ppg)</small></div></div>`).join('')}
function trTier(p){return p>=.2?['Elite',4]:p>=.07?['Good',3]:p>-.07?['Average',2]:p>-.2?['Below average',1]:['Poor',0]}
function trNeedsDiffHTML(b,a){let n0=trNeeds(b,'later'),n1=trNeeds(a,'later');return `<div class="trNeeds">${n0.map((x,i)=>{let y=n1[i],t0=trTier(x.pct),t1=trTier(y.pct),d=t1[1]-t0[1],cls=d>0?'up':d<0?'dn':'ok';return `<div class="trNd ${cls}"><b>${x.pos}</b><i class="trGr ${cls}">${d>0?'▲ ':d<0?'▼ ':''}${d?`${t0[0]} → ${t1[0]}`:`${t1[0]} (no change)`}</i><small>Starter level ${trN(x.mine)} → ${trN(y.mine)} ppg (league starter ${trN(y.lg)})</small><small>${x.startable} → ${y.startable} startable${y.startable<y.ideal?` (aim for ${y.ideal})`:' ✓'}</small></div>`}).join('')}</div>`}
function trNeedsHTML(nd,ndNow){return `<div class="trNeeds">${nd.map((n,i)=>{let nw=ndNow&&ndNow[i],short=nw&&nw.grade==='Need'&&n.grade!=='Need';return `<div class="trNd ${n.grade==='Strength'?'up':n.grade==='Need'?'dn':'ok'}"><b>${n.pos}</b><i class="trGr ${n.grade==='Strength'?'up':n.grade==='Need'?'dn':'ok'}">${trTier(n.pct)[0]}</i><small>${trN(n.mine)} ppg vs ${trN(n.lg)} for a league starter</small><small>${n.startable} startable${n.startable<n.ideal?` (aim for ${n.ideal})`:' ✓'}${short?' • thin right now only, injured starters return':''}</small><small class="trTap">Compare rooms &rsaquo;</small></div>`}).join('')}</div>`}
function trRecInput(side){let r=TR.rec[side]||[0,0];return `<span class="trRec">Record <input type="number" min="0" max="17" inputmode="numeric" class="trRi" data-side="${side}" data-i="0" value="${r[0]}"> – <input type="number" min="0" max="17" inputmode="numeric" class="trRi" data-side="${side}" data-i="1" value="${r[1]}"></span>${trStSel(side)}`}
/* ---------- Quick trade ---------- */
var TRNUM=false;
function trQuick(){TRNUM=true;let h;try{h=trQuickRaw()}finally{TRNUM=false}TRCVmap=null;return h}
function trQuickSide(who,inc,out,gapPct,mxv){let you=who==='you',P=you?'You':'They',g='',pl=(n,w)=>n+' '+w+(n===1?'':'s'),pi={},po={},good=[],care=[];
 inc.forEach(v=>pi[v.p.pos]=(pi[v.p.pos]||0)+1);out.forEach(v=>po[v.p.pos]=(po[v.p.pos]||0)+1);
 let top=inc.slice().sort((a,b)=>b.tv-a.tv)[0],topO=out.slice().sort((a,b)=>b.tv-a.tv)[0];
 TRPOS.forEach(pos=>{let a=pi[pos]||0,b=po[pos]||0;if(a>b){good.push(`${P} ${you?'are':'are'} thin at ${pos}, so adding ${pl(a-b,pos)} fills a real hole.`);care.push(`${P} already ${you?'have':'have'} 3 or more startable ${pos}s, so the extra ${pos} would sit on the bench.`)}else if(b>a){care.push(`${P} give${g} up ${pl(b-a,pos)} and ${you?'need':'need'} another startable ${pos} to take the spot.`);good.push(`${P} ${you?'have':'have'} ${pos} depth to spare.`)}});
 if(inc.length<out.length){good.push(`${P} want${g} one top player instead of several mid ones. Fewer, better starters usually win more, and the open roster spot can add a free agent.`);care.push(`${P} ${you?'are':'are'} thin on depth. With byes and injuries coming, giving up extra bodies hurts.`)}
 else if(inc.length>out.length){good.push(`${P} need${g} cover for byes and injuries.`);care.push(`Only some of the ${inc.length} will start, and ${you?'you':'they'} must drop ${pl(inc.length-out.length,'player')} to make room.`)}
 if(top&&topO){if(top.tv>topO.tv*1.15)good.push(`${P} get${g} the best player in the deal: ${trL(top.p)} (${trN(top.later)} points a game).`);else if(topO.tv>top.tv*1.15)care.push(`${P} give${g} up the best player in the deal: ${trL(topO.p)}.`)}
 inc.forEach(v=>{let nA=v.nowAvg;if(v.pl.R>0)care.push(`${trL(v.p)} is ${v.pl.label||'out'} and does not help until about Week ${v.retW}.${v.later>=trCtx().start[v.p.pos]?' Fine for a team that can stash him for the stretch run.':''}`);else if(v.cause&&v.boost>=.8)care.push(`${trL(v.p)} is getting extra work while ${trL(v.cause.p)} is out (${trN(v.base+v.boost)} a game now, ${trN(v.later)} after ~Week ${v.cause.retW}). That boost fades.`);else if(nA!=null&&nA-v.later>=1.2)good.push(`${trL(v.p)} is producing about ${trN(nA)} a game now, so it suits a team pushing for the next few weeks.`);if(!v.pl.gone&&v.pl.R===0&&v.bye>=META.next_week&&v.bye<=META.next_week+1)care.push(`${trL(v.p)} has a bye in Week ${v.bye}.`)});
 if(!good.length)good.push(`${P} want${g} the better fit at those positions.`);if(!care.length)care.push(`${P} would be giving up the stronger long-term piece.`);
 let un=[...new Set(good)].slice(0,4),cu=[...new Set(care)].slice(0,4),adv=gapPct>=.05?`On value ${you?'you':'they'} come out ahead by ${Math.round(gapPct*100)}%`:gapPct<=-.05?`On value ${you?'you':'they'} give${g} up ${Math.round(-gapPct*100)}%`:'Even on value',
 gets=inc.map(v=>`${trL(v.p)} <i>${v.p.pos}</i>`).join(' + ');
 return `<div class="trSB ${gapPct>=.05?'good':gapPct<=-.05?'bad':'ok'}"><div class="trSBh"><span>${you?'If you make this trade':'From their side'}</span><strong>${adv}</strong></div><div class="trSBl" style="margin-bottom:8px">${P} get${g}: ${gets}</div><div class="tsec">Works well if</div><ul class="trHints">${un.map(h=>`<li>${h}</li>`).join('')}</ul><div class="tsec" style="margin-top:10px">Think twice if</div><ul class="trHints">${cu.map(h=>`<li>${h}</li>`).join('')}</ul></div>`}

var TRF={pos:[],n:15,two:false,pos2:'ANY',go:false,key:'',real:true,team:-1,nb:0,sl:['ANY','ANY','ANY']};
function trNotice(title,html){let m=document.createElement('div');m.className='trModal';m.innerHTML=`<div class="trModalB"><b>${title}</b><p>${html}</p><button type="button" class="trAsk">Okay</button></div>`;m.onclick=e=>{if(e.target===m||e.target.tagName==='BUTTON')m.remove()};document.body.appendChild(m)}
function trFindList(){let LGO=lgOn()?lgOwned():null,c=trCtx(),give=TR.give.filter(i=>c.V[i]&&!c.V[i].pl.gone);if(!give.length)return null;let Gt=trSide(give,1).tot,want=TRF.two?Gt*.66:Gt,used=new Set(TR.give),
 pool=c.vs.filter(v=>!used.has(v.p.id)&&!v.pl.gone&&v.pl.R<=2&&v.tv>0&&(!LGO||LGO[v.p.id])&&(!TRF.pos.length||TRF.pos.includes(v.p.pos))).map(v=>({v,g:(v.tv-want)/Math.max(v.tv,want,1)})),res=[];
 for(const band of [.1,.18,.3,.45]){res=pool.filter(x=>Math.abs(x.g)<=band);if(res.length>=30)break}
 res.sort((a,b)=>Math.abs(a.g)-Math.abs(b.g));res=res.slice(0,30);
 let tv2=null,ex=[];if(TRF.two){tv2=Math.max(0,(Gt-want)/.85);ex=c.vs.filter(v=>!used.has(v.p.id)&&!v.pl.gone&&v.pl.R<=1&&(TRF.pos2==='ANY'||v.p.pos===TRF.pos2)&&v.tv>0).sort((a,b)=>Math.abs(a.tv-tv2)-Math.abs(b.tv-tv2)).slice(0,3)}
 return {res,Gt,want,tv2,ex,give}}
function trFinderHTML0(){let k=TR.give.join(',');if(TRF.key!==k){TRF.key=k;TRF.go=false;TRF.n=15;TRF.lgo=false}
 let chip=(p)=>`<button type="button" class="trfPos trCh${TRF.pos.includes(p)?' on':''}" data-p="${p}">${p}</button>`,c2=(p)=>`<button type="button" class="trfP2 trCh${TRF.pos2===p?' on':''}" data-p="${p}">${p==='ANY'?'Any':p}</button>`;
 let head=`<div class="trCard trFind"><div class="ph"><div><b>Find trades</b><small class="mut" style="display:block;margin-top:2px">Add the players you would send above, pick a position if you want one, and we find a player worth about the same.</small></div></div><div class="trSortBar"><div><span>Position</span><button type="button" class="trfPos trCh${TRF.pos.length?'':' on'}" data-p="ALL">Any</button>${['WR','RB','TE','QB'].map(chip).join('')}</div></div><div class="trfAct"><button type="button" class="trAsk trfGo"${TR.give.length?'':' disabled'}>${TRF.go?'Search again':'Find trades'}</button><label class="trfTwo"><input type="checkbox" class="trfTwoC"${TRF.two?' checked':''}> I want two players back</label></div>${TRF.two?`<div class="trSortBar" style="margin-top:8px"><div><span>Second player</span>${['ANY','WR','RB','TE','QB'].map(c2).join('')}</div></div>`:''}`;
 if(!TR.give.length)return head+'<p class="tnote">Add at least one player to "You send" to search.</p></div>';
 if(!TRF.go)return head+'</div>';
 let F=trFindList();if(!F)return head+'<p class="tnote">Those players are not on a roster right now.</p></div>';
 let LGOo=lgOn()?lgOwned():{},sec2=v=>{if(!TRF.two||!lgOn())return '';let o=TR.lg.find(t=>t.ids.includes(v.p.id));if(!o)return '';let V=trCtx().V,cd=o.ids.filter(i=>i!==v.p.id&&V[i]&&!V[i].pl.gone&&(TRF.pos2==='ANY'||V[i].p.pos===TRF.pos2)).map(i=>V[i]).sort((a,b)=>Math.abs(a.tv-F.tv2)-Math.abs(b.tv-F.tv2))[0];return cd?' \u2022 second: '+trEsc(cd.p.name):''},mx=trCtx().mx,show=F.res.slice(0,TRF.n),nt=TRF.two&&lgOn()?`<div class="trfNote"><b>Two players:</b> each offer shows the first player, plus a second one from the same team worth about <b>${trN(trDisp(100*F.tv2/mx))}</b> in value.</div>`:TRF.two?`<div class="trfNote"><b>Two players:</b> we search one player at a time because we do not know the other team's roster. Each offer below is the first player. Then ask for a second player worth about <b>${trN(trDisp(100*F.tv2/mx))}</b> in value${F.ex.length?` (players like ${F.ex.map(v=>trL(v.p)).join(', ')})`:''}${TRF.pos2!=='ANY'?`, ideally a ${TRF.pos2}`:''}. Check that team has one before you ask.</div>`:'';
 let rows=show.map(x=>{let v=x.v,g=x.g,gt=Math.abs(g)<.06?'Even value':g>0?`He is worth about ${Math.round(Math.abs(g)*100)}% more`:`You give about ${Math.round(Math.abs(g)*100)}% more`;return trRow(v.p.id,`<button type="button" class="trAsk trfPick" data-id="${v.p.id}">Check</button>`,gt+(TRF.two?' (first player)':'')+(LGOo[v.p.id]?' \u2022 on '+trEsc(LGOo[v.p.id]):'')+sec2(v))}).join('');
 return head+nt+(rows?`<div class="trfList">${rows}</div><div class="trMoreW">${F.res.length>TRF.n&&TRF.n<30?`<button type="button" class="trAsk trfMore">Load ${Math.min(5,F.res.length-TRF.n,30-TRF.n)} more</button>`:''}<small>Showing ${show.length} of ${F.res.length}</small></div><p class="tnote">Offers are matched on value only, and we do not see the other team's roster, so a player may not fit their needs. Tap Check to see the full analysis.</p>`:'<p class="tnote">No players near that value at this position. Try Any position or add another player.</p>')+'</div>'}
function trQuickRaw(){TRCVmap=null;let G=trSide(TR.give,TR.get.length,trGrp('their')),R=trSide(TR.get,TR.give.length,trGrp('my')),have=G.it.length&&R.it.length,list=(S,side)=>S.it.map(x=>trRow(x.v.p.id,`<button type="button" class="tx trDel" data-side="${side}" data-id="${x.v.p.id}" title="Remove">✕</button>`,x.w<1?`counts ${Math.round(x.w*100)}%`:'')).join('')||'<div class="trEmpty">Search for a player to add.</div>',out='';
 if(have){let a=R.tot,b=G.tot,mx=Math.max(a,b,1),gap=(a-b)/mx,ag=Math.abs(gap),a4=R.tot4,b4=G.tot4,m4=Math.max(a4,b4,1),g4=(a4-b4)/m4,
  lab=ag<.08?'Fair trade':gap>0?(ag>=.25?'Big win for you':'You win this trade'):(ag>=.25?'Big loss for you':'You lose this trade'),cls=ag<.08?'even':gap>0?'win':'lose',hints=[],
  sh=g=>Math.abs(g)<.08?'about even':g>0?`you win by ${Math.round(Math.abs(g)*100)}%`:`you lose by ${Math.round(Math.abs(g)*100)}%`;
  if(Math.abs(g4-gap)>=.2||(Math.abs(g4)>=.08&&Math.abs(gap)>=.08&&g4*gap<0))hints.push(g4>gap?'This trade looks better right now than for the full season. Injured players coming back or fading roles change the picture later.':'This trade looks better for the full season than for the next month. You may wait on an injured player.');
  if(G.it.length>R.it.length)hints.push(`You send ${G.it.length} for ${R.it.length}, so you open ${G.it.length-R.it.length} roster spot${G.it.length-R.it.length>1?'s':''}. Make sure the extra spot gets a useful pickup.`);
  if(R.it.length>G.it.length)hints.push(`You get ${R.it.length} for ${G.it.length}, so you will have to drop someone. The extra players only help if they can start for you.`);
  hints.push(R.it[0].v.tv>G.it[0].v.tv?'You are getting the best player in the deal, which usually matters most.':'You are giving up the best player in the deal.');
  R.it.concat(G.it).forEach(x=>{let w=trWarn(x.v);if(w&&(x.v.pl.R>0||x.v.cause))hints.push(`<b>${trL(x.v.p)}</b>: ${x.v.pl.R>0?`${x.v.pl.label||'out'}, back ~Week ${x.v.retW}.`:`extra work now, ${trN(x.v.later)} a game after ${trL(x.v.cause.p)} returns (~Week ${x.v.cause.retW}).`}`)});
  let fix='';if(ag>=.12){let need=Math.abs(b-a)/.7,used=new Set(TR.give.concat(TR.get)),cs=trCtx().vs.filter(v=>!used.has(v.p.id)&&!v.pl.gone&&v.pl.R<=1&&v.tv>=need*.6&&v.tv<=need*1.4).sort((x,y)=>Math.abs(x.tv-need)-Math.abs(y.tv-need)).slice(0,4);
   if(cs.length)fix=`<div class="trFix"><b>${gap<0?'To even it out, ask for':'They would likely want'} about one more player value around ${trN(trDisp(100*need/trCtx().mx))}:</b> ${cs.map(v=>`<span>${trL(v.p)} <i>${v.p.pos} ${trN(v.val)}</i></span>`).join('')}</div>`}
  let onT='<p class="tnote" style="text-align:center">Quick trade only looks at the players, not your team. To see how a trade changes your own lineup, use Full team trade and tap Just my team.</p>';
  let rm=Math.max(...R.it.map(x=>x.v.tv)),gm=Math.max(...G.it.map(x=>x.v.tv)),pct=Math.round(ag*100),close=ag<.05?'basically even':ag<.12?'close':ag<.25?'a little uneven':'lopsided',
   lab2=ag<.05?'Basically even':ag<.12?(gap>0?'Close, slight edge to you':'Close, slight edge to them'):ag<.25?(gap>0?'Leans your way':'Leans their way'):(gap>0?'Big edge to you':'Big edge to them'),cls2=ag<.12?'even':gap>0?'win':'lose',
   narr=ag<.05?'On value alone neither side is overpaying. It comes down to which team needs what.':ag<.12?`On value alone this is close (${pct}% apart). Small needs, like a thin position, could easily tip it either way.`:ag<.25?`${gap>0?'You':'They'} come out ${pct}% ahead on value. The other side would need a reason, like a position of need, to say yes.`:`${gap>0?'You':'They'} come out about ${pct}% ahead on value. The other side would probably want more added.`,
   topG=G.it.slice().sort((x,y)=>y.v.tv-x.v.tv)[0].v,topR=R.it.slice().sort((x,y)=>y.v.tv-x.v.tv)[0].v,
   tile=(t,v,c)=>`<div><small>${t}</small><b class="${c||''}">${v}</b></div>`,
   tiles=`<div class="trCard"><div class="trSBg trQT">${tile('Gap on value',(Math.abs(gap)<.05?'Even':(gap>0?'+':'-')+pct+'%'),gap>=.05?'up':gap<=-.05?'dn':'')}${tile('Next 4 weeks',sh(g4).replace('you win by ','+').replace('you lose by ','-').replace('about even','Even'),Math.abs(g4)<.05?'':g4>0?'up':'dn')}${tile('Rest of season',sh(gap).replace('you win by ','+').replace('you lose by ','-').replace('about even','Even'),Math.abs(gap)<.05?'':gap>0?'up':'dn')}${tile('Best player (ppg)',`${trN(topG.later)} → ${trN(topR.later)}`)}</div></div>`;
  out=`<div class="trVerdict ${cls2}"><div class="trvK">Trade check</div><strong>${lab2}</strong><div class="trvS">${narr}</div>${trStandHint()}<div class="trBar"><div class="trbG" style="width:${b/(a+b||1)*100}%"></div><div class="trbR" style="width:${a/(a+b||1)*100}%"></div></div><div class="trBarL"><span>You send <b>${trN(100*b/trCtx().mx)}</b></span><span>You get <b>${trN(100*a/trCtx().mx)}</b></span></div><p class="tnote" style="text-align:center;margin:8px 0 0">These totals use true value, where one star is worth far more than two role players. The player numbers above are on a friendlier scale, so they will not add up to the total.</p>${fix}</div>`+tiles+(lgQuickOK()?lgQuickReal(TR.give,TR.get):`<div class="trCols trSplit">${trQuickSide('you',R.it.map(x=>x.v),G.it.map(x=>x.v),gap,mx)}${trQuickSide('they',G.it.map(x=>x.v),R.it.map(x=>x.v),-gap,mx)}</div>`+onT)}
 else out=`<div class="trVerdict even"><div class="trvK">Verdict</div><strong>Add players to both sides</strong><div class="trvS">Pick who you would send and who you would get. Try the example to see how it reads.</div></div>`;
 return `<div class="trCols"><div class="trCard"><div class="ph">You send</div>${trSearchBox('trQg','Search a player to send')}${list(G,'give')}</div><div class="trCard"><div class="ph">You get</div>${trSearchBox('trQr','Search a player to get')}${list(R,'get')}</div></div>${trFinderHTML()}${out}<div class="trFoot"><button type="button" class="reset" id="trEx">Try an example</button><button type="button" class="reset" id="trClr">Clear</button></div><p class="tnote">Value is points above a replacement player in a ${TR.n}-team ${TR.sf?'superflex':'1-QB'} PPR league, for the rest of the season. It blends Mania Rating, this week's projection and our estimate for later, and counts byes, injuries and returns. For a side with several players the best counts in full and each next one a little less, since only so many can start.</p>`}
/* ---------- Rosters ---------- */
function trRoster(side,title,withSend){let ids0=TR[side],oth=side==='my'?TR.their:TR.my;TRCVmap=(oth.length>=trNeedStart()&&ids0.length)?trValsFor(oth,ids0,side==='my'?'to them':'to you'):null;let h=trRosterRaw(side,title,withSend);TRCVmap=null;return h}
function trRosterRaw(side,title,withSend){let ids=TR[side],V=trCtx().V,sorted=ids.map(i=>V[i]).filter(Boolean).sort((a,b)=>(a.pl.R>0)-(b.pl.R>0)||TRO[a.p.pos]-TRO[b.p.pos]||b.raw-a.raw),sd=TR.send[side],need=TR.st.QB+TR.st.RB+TR.st.WR+TR.st.TE+TR.st.FLEX+(TR.sf?1:0);
 let rows=sorted.map(v=>{let on=sd.includes(v.p.id);return trRow(v.p.id,`${withSend?`<button type="button" class="trSend${on?' on':''}" data-side="${side}" data-id="${v.p.id}">${on?'Sending':'Trade'}</button>`:''}${side==='my'&&withSend?`<button type="button" class="trLock${(TR.lock||[]).includes(v.p.id)?' on':''}" data-id="${v.p.id}" title="Untouchable: we will never suggest trading him">${(TR.lock||[]).includes(v.p.id)?'\uD83D\uDD12 Kept':'Keep'}</button>`:''}<button type="button" class="tx trDelR" data-side="${side}" data-id="${v.p.id}" title="Remove">✕</button>`)}).join('');
 let healthy=sorted.filter(v=>!(v.pl.R>0)).length,bn=Math.max(0,healthy-need),irN=sorted.length-healthy;
 return `<div class="trCard trRoster"><div class="ph">${title} <span class="trCount">${sorted.length} players</span></div>${withSend&&!TR.solo?`<div class="trRecRow">${trRecInput(side)}</div>`:''}${trSearchBox('trR'+side,'Add a player to this roster')}${rows?trD('rl'+side,'Players','show or hide',rows,!(withSend&&(TR.send.my.length||TR.send.their.length)),'trRL'):''}${rows?'':'<div class="trEmpty">Add every player on the roster, injured ones too. We pick the best lineup and treat injured players as IR.</div>'}${sorted.length?`<div class="trMeta">${need} starters • ${bn} bench${irN?` • ${irN} injured`:''}. We assume the bench is what you entered${healthy<need+3?', so add your full bench for better results':''}.</div><div class="trFoot l"><button type="button" class="reset trClrR" data-side="${side}">Clear roster</button></div>`:''}</div>`}
const trSgn=v=>(v>=0?'+':'')+trN(v);
function trDealsHTML(){let ds=trDeals(TR.my,TR.their),rx=false;if(!ds.length){ds=trDeals(TR.my,TR.their,true);rx=!!ds.length}if(!ds.length)return '<p class="tnote">No clean win-win deal found between these two rosters. Try tapping Trade on a few players to test your own idea.</p>';
 return (rx?'<p class="tnote">No deal helps both lineups. These are fair on value and help you most while barely costing them, so they would mostly be accepted on value alone.</p>':'')+ds.map((d,i)=>trDealCard(d,`<button type="button" class="trAsk trUse" data-i="${i}">Test this trade</button>`)).join('')}
function trDealCard(d,btn){let pl=a=>a.map(x=>`<div class="tdP">${thumb(x.p)}<div><b>${trEsc(x.p.name)}</b><small>${x.p.pos} &middot; ${x.p.team}</small></div></div>`).join('');return `<div class="trDeal tdN"><div class="tdB"><div class="tdS"><small>You send</small>${pl(d.A)}</div><div class="tdX"><i>&#8644;</i></div><div class="tdS"><small>You get</small>${pl(d.B)}</div></div><div class="trDealM">Your lineup <b class="${d.la>=0?'up':'dn'}">${trWord(d.la)}</b> &bull; theirs <b class="${d.lb>=0?'up':'dn'}">${trWord(d.lb)}</b> &bull; value ${Math.abs(d.gap)<.06?'even':Math.abs(d.gap)>=.2?'about '+Math.round(Math.abs(d.gap)*100)+'% '+(d.gap>0?'in your favor':'in theirs'):d.gap>0?'slightly in your favor':'slightly in theirs'}</div>${d.why?`<div class="trWhy">${d.why}</div>`:''}${btn}</div>`}
/* League finder: the same win-win search as "Suggest a fair trade", run against every saved league team. */
var TRLG={on:false,key:'',res:[]};
function trLgDeals(){let key=JSON.stringify([TR.my,TR.lg,trCtx().key]);if(TRLG.key!==key){TRLG.key=key;TRLG.res=TR.lg.map((t,ti)=>{let ds=trDeals(TR.my,t.ids),rx=!ds.length;if(rx)ds=trDeals(TR.my,t.ids,true);return {ti,rx,ds:ds.slice(0,2)}}).filter(x=>x.ds.length).sort((a,b)=>a.rx-b.rx||b.ds[0].score-a.ds[0].score)}return TRLG.res}
function trLgDealsHTML(){let R=trLgDeals();return R.length?(R.some(x=>x.rx)?'<p class="tnote">Teams marked <b>leans your way</b> have no deal that helps both lineups. Those deals are fair on value and help you most while barely costing them.</p>':'')+R.map(x=>`<div class="tsec">${trEsc(TR.lg[x.ti].n)}${x.rx?' &middot; leans your way':''}</div>`+x.ds.map((d,i)=>trDealCard(d,`<button type="button" class="trAsk trLgUse" data-t="${x.ti}" data-i="${i}">Test this trade</button>`)).join('')).join(''):'<p class="tnote">No trade helps both lineups with any team in your league right now.</p>'}
var TRV={lv:'now',lm:'proj'},TRSHOWF=null,TRSUM='',TRSUG=false;
/* Full-team Trade Analyzer: the picked players and both rosters show right away, but the full
   breakdown (lineups, needs, season outlook, other deals) waits for an explicit click, so it always
   uses the current logic instead of showing a stale grade the moment you tap a second player. A trade
   someone shared with you (TR.shared) or a league-saved trade skips the click and opens unlocked. */
var TRTC={key:'',on:false,busy:false};
document.addEventListener('click',function(e){var t=e.target.closest&&e.target.closest('#trTcGo');if(!t)return;TRTC.busy=true;trRenderAll();
 var stages=['Checking lineups...','Checking depth and injuries...','Checking rest-of-season outlook...','Checking other deals...'],k=0;
 (function step(){var b=document.getElementById('trTcBar'),tx=document.getElementById('trTcTxt');if(b)b.style.width=Math.round(100*(k+1)/stages.length)+'%';if(tx)tx.textContent=stages[k];k++;if(k<stages.length)setTimeout(step,380);else setTimeout(function(){TRTC.busy=false;TRTC.on=true;trRenderAll()},280)})()});
function trGainStars(owner,id){let v=trCtx().V[id],pos=v.p.pos,wk=Math.max(1,trWeeks('ros').length),g=trMarg(owner,id,'ros')/wk,sc=pos==='QB'?(TR.sf?1:.75):pos==='TE'?1.2:1,x=g*sc,P=[[0,0],[.15,.5],[.5,1.5],[1,2.5],[1.6,3.5],[2.4,4.5],[3.4,5]],st=5;if(x<=0)st=0;else for(let i=1;i<P.length;i++)if(x<=P[i][0]){let a=P[i-1],b=P[i];st=a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0]);break}
 let fl=trStarN(trCV(trMarg(owner,id),id))*.7;return {stars:Math.round(Math.max(st,fl)*2)/2,g}}
function trValsFor(owner,ids,who){let V=trCtx().V,o={};ids.forEach(i=>{if(V[i]&&!V[i].pl.gone){let q=trGainStars(owner,i);o[i]={val:trCV(trMarg(owner,i),i),stars:q.stars,g:q.g,who}}});return o}
function trShowF(){let lv=TRV.lv,lm=TRV.lm;return v=>{if(lm==='mania')return [v.p.mania==null?'—':Math.round(v.p.mania),'mania'];if(lm==='out')return [Math.round(v.outlook),'outlook'];let x=lv==='now'?v.nowP:v.later;return [x==null?'—':trN(x),lv==='now'?'this week':'full strength']}}
function trLnKnobs(){let b=(k,v,t)=>`<button type="button" class="tsb trk${TRV[k]===v?' on':''}" data-k="${k}" data-v="${v}">${t}</button>`;return `<div class="trKn"><div class="tpre">${b('lv','now','This week')}${b('lv','later','Full strength')}</div><div class="tpre">${b('lm','proj','Expected pts')}${b('lm','mania','Mania Rating')}${b('lm','out','Outlook')}</div></div>`}
function trLnBlock(title,ids,mark){TRSHOWF=trShowF();let L=trLineup(ids,TRV.lv),c=trCtx(),set=new Set(L.st.filter(x=>x.v).map(x=>x.v.p.id)),bn=ids.map(i=>c.V[i]).filter(v=>v&&!v.pl.gone&&!set.has(v.p.id)).sort((a,b)=>(a.pl.R>0)-(b.pl.R>0)||b.outlook-a.outlook),
 h=`<div class="trLnT"><b>${title}</b><span>${trN(L.tot)} expected points ${TRV.lv==='now'?'this week':'at full strength (everyone healthy, no byes)'}</span></div><div class="trLn"><div><div class="tsec">Starters</div>${trLineHTML(L,mark)}</div><div><div class="tsec">Bench</div>${bn.length?bn.map(v=>trRow(v.p.id,'',v.pl.R>0?'':(TRV.lv==='now'&&v.nowP==null?'Bye week':''),mark&&mark.has(v.p.id)?'<b class="trNew">NEW</b>':'')).join(''):'<div class="trEmpty">No bench players</div>'}</div></div>`;TRSHOWF=null;return h}
function trLevel(d){return d>=1?['Gets better','good']:d>.25?['Gets a bit better','good']:d>=-.25?['Stays about the same','ok']:d>-1?['Gets a bit worse','bad']:['Gets worse','bad']}
function trWord(x){return x>=1.5?'Much better':x>=.4?'Better':x>-.4?'About even':x>-1.5?'Worse':'Much worse'}
function trSeason(b,a,inc,title){let wk=trWeeks('ros'),w0=wk.map(w=>trLineupW(b,w).tot),w1=wk.map(w=>trLineupW(a,w).tot),d=w1.map((x,i)=>x-w0[i]),t0=w0.reduce((s,x)=>s+x,0),t1=w1.reduce((s,x)=>s+x,0),dt=t1-t0,up=d.filter(x=>x>.05).length,dn=d.filter(x=>x<-.05).length,mxa=Math.max(1,...d.map(Math.abs)),W=wk.length*30,
 bars=d.map((x,i)=>{let h=Math.abs(x)/mxa*32,y=x>=0?50-h:50;return `<rect x="${i*30+6}" y="${y.toFixed(1)}" width="18" height="${Math.max(h,1).toFixed(1)}" rx="3" fill="${x>.05?'#22a45d':x<-.05?'#e2505b':'#c9d1de'}"><title>Week ${wk[i]}: ${trSgn(x)}</title></rect><text x="${i*30+15}" y="${x>=0?50-h-3:50+h+10}" font-size="8.5" text-anchor="middle" fill="#5a6b86">${Math.abs(x)>=.5?trSgn(x).replace(/\.0$/,''):''}</text><text x="${i*30+15}" y="104" font-size="9" text-anchor="middle" fill="#8a99b1">${wk[i]}</text>`}).join(''),
 ex=inc.filter(v=>v.pl.R>0&&wk.includes(v.retW)).map(v=>`${trL(v.p)} is back around Week ${v.retW}: your lineup gets stronger that week.`),
 ex2=[];let best=d.indexOf(Math.max(...d)),worst=d.indexOf(Math.min(...d));if(Math.max(...d)>.5)ex2.push(`Biggest boost: Week ${wk[best]}.`);if(Math.min(...d)<-.5)ex2.push(`Thinnest week: Week ${wk[worst]}.`);
 return `<div><div class="tsec">${title}</div><div class="trSeasonT"><b class="${dt>=.05?'up':dt<=-.05?'dn':''}">${trWord(dt/Math.max(1,wk.length))}</b><span>for your starting lineup over the rest of the season</span></div><div class="trSBl">Better in <b>${up}</b> of ${wk.length} weeks${dn?`, worse in <b>${dn}</b>`:''}. ${ex2.join(' ')}</div>${(TR.espnPj&&Object.keys(TR.espnPj).length)?'<div class="trSBl" style="color:#6b7a94;font-size:11.5px;margin-top:4px">Future weeks use your league’s ESPN projections; this week uses Fantasy Mania’s own.</div>':''}${ex.length?`<ul class="trHints">${ex.map(h=>`<li>${h}</li>`).join('')}</ul>`:''}</div>`}
function trSideBox(name,d,na,la,pa,up,notes,l0,l1,nowLater){let lv=trLevel(d),cell=(t,x)=>`<div><small>${t}</small><b class="${x>=.05?'up':x<=-.05?'dn':''}">${trWord(x)}</b></div>`;
 return `<div class="trSB ${lv[1]}"><div class="trSBh"><span>${name}</span><strong>${lv[0]}</strong></div><div class="trSBg">${cell('Next 4 weeks',na)}${cell('Whole season',la)}${trWeeks('play').length?cell('Playoffs',pa):''}</div><div class="trSBl">Lineup this week: <b>${trN(l0)} → ${trN(l1)}</b>. Starting spots: <b>${up.up}</b> better${up.dn?`, ${up.dn} worse`:''}.</div>${nowLater?`<p class="trSBn">${nowLater}</p>`:''}<ul class="trHints">${notes.map(h=>`<li>${h}</li>`).join('')}</ul></div>`}
function trLgBar(){let o=TR.lg.map((t,i)=>`<option value="${i}"${i===TR.lgi?' selected':''}>${trEsc(t.n)} (${t.ids.length})</option>`).join('');
 return `<div class="trLg"><b>Trade partner</b><select id="trLgSel"><option value="-1">${TR.their.length&&TR.lgi<0?'Unsaved team':'New team'}</option>${o}</select>${TR.lgi>=0?'<button type="button" class="reset" id="trLgDel">Remove from league</button>':TR.their.length?'<button type="button" class="reset" id="trLgSave">Save to league</button>':''}</div>`}
/* ESPN import: the League > Rosters page copied whole (Ctrl+A, Ctrl+C). ESPN has no login-free API for private leagues,
   so we read the page text. Each team is its name then a "(W-L-T)" line; each player is "NameName", then "Name", then team,
   injury tag and position lines. ESPN lists the viewer's own team first. Kickers and defenses are read too. */
function trEspnKey(s){return s.toLowerCase().replace(/\b(jr|sr|ii|iii|iv|v)\b\.?/g,'').replace(/[^a-z]/g,'')}
function trEspnSettings(L,teams){let SL=/^(QB|RB|WR|TE|FLEX|OP|SUPERFLEX|D\/ST|K|Bench|IR)(\s|$)/,prevOK=x=>x==null||/^(ACQ|Draft|Free Agency|Trade|Waivers|Empty)$/.test(x)||/Empty$/.test(x),best=null;
 teams.forEach((T,k)=>{let end=k+1<teams.length?teams[k+1].i0-1:L.length,c={QB:0,RB:0,WR:0,TE:0,FLEX:0,OP:0,K:0,DST:0,Bench:0,IR:0},n=0;
  for(let i=T.i0+1;i<end;i++){let l=L[i],m=l.match(SL);if(!m||!prevOK(L[i-1]))continue;let nx=L[i+1];if(l===m[1]&&nx&&/^(Draft|Free Agency|Trade|Waivers)$/.test(nx))continue;let t=m[1];if(t==='SUPERFLEX')t='OP';if(t==='D/ST')t='DST';c[t]++;n++}
  if(!best||n>best.n)best={n,c}});
 if(!best||best.c.QB+best.c.RB+best.c.WR<3)return null;let c=best.c,sf=c.OP>0;
 return {n:teams.length,QB:Math.max(1,c.QB),RB:c.RB,WR:c.WR,TE:c.TE,FLEX:c.FLEX+c.OP,sf,K:c.K>0,DST:c.DST>0,bench:c.Bench,ir:c.IR}}
function trEspnFlat(txt){txt=(txt||'').replace(/ /g,' ').replace(/\t/g,' ');let nl=(txt.match(/\n/g)||[]).length;if(!/SLOT\s+PLAYER\s+ACQ/.test(txt)||nl>60)return txt;
 let flat=txt.replace(/\s+/g,' '),nav=[],m,rn=/•\s*([^•()]+?)\s*\([A-Z0-9]{2,6}\)/g;while((m=rn.exec(flat)))nav.push(m[1].trim());
 let rh=/\((\d+)-(\d+)(?:-(\d+))?\)\s+SLOT\s+PLAYER\s+ACQ\s+/g,H=[];while((m=rh.exec(flat)))H.push({i:m.index,e:m.index+m[0].length,w:m[1],l:m[2],t:m[3]||'0'});if(!H.length)return txt;
 let out=[],prev=0,flatName='';
 H.forEach((h,k)=>{let seg=flat.slice(prev,h.i),name;
  if(k===0){let best='';nav.forEach(n=>{if(n.length>best.length&&seg.toLowerCase().replace(/\s+$/,'').endsWith(n.toLowerCase()))best=n});if(!best){let w=seg.replace(/\s+$/,'').split(' ');for(let n=Math.min(7,w.length);n>=1;n--){let c=w.slice(-n).join(' '),ix=flat.indexOf(c+' (');if(ix>=0&&/^\([A-Z0-9]{2,6}\)/.test(flat.slice(ix+c.length+1,ix+c.length+9))){best=c;break}}}
  name=best?seg.replace(/\s+$/,'').slice(-best.length):seg.trim().split(' ').slice(-2).join(' ');let sg=seg.replace(/\s+$/,'');flatName=sg.indexOf('League Rosters')>=0?sg.slice(sg.indexOf('League Rosters')+14,sg.length-name.length).trim():''}
  else name=seg.replace(/^\s*View Team\s*(?:\([^)]*\))?\s*(?:Propose Trade\s*(?:\([^)]*\))?)?\s*/,'').trim();
  let ve=flat.indexOf('View Team',h.e),end=ve<0?flat.length:ve,block=flat.slice(h.e,end),tail=ve<0?'':flat.slice(ve,k+1<H.length?H[k+1].i:flat.length),prop=/Propose Trade/.test(tail.slice(0,400));prev=ve<0?flat.length:ve;
  let lines=[name,'('+h.w+'-'+h.l+'-'+h.t+')','SLOT','PLAYER','ACQ'];
  block.split(/\s+(?:Draft|Free Agency|Trade|Waivers)(?=\s|$)/).forEach(r=>{r=r.trim();if(!r||/^IR Empty$/i.test(r))return;let x=r.match(/^(QB|RB|WR|TE|FLEX|OP|D\/ST|K|Bench|IR)\s+(.*?)\s+([A-Z]{2,3}|FA)\s+(QB|RB|WR|TE|K|D\/ST)$/);if(!x)return;let nm=x[2].replace(/\s+(Q|O|IR|DTD|D|SSPD|PUP)$/,'').trim(),dd=nm.match(/^(.+)\1\s+\1$/)||nm.match(/^(.+)\1$/);if(dd)nm=dd[1].trim();if(/^Empty$/i.test(nm))return;lines.push(x[1]+' '+nm,x[3],x[4],'Draft')});
  lines.push('View Team (x)'+(prop?'Propose Trade (y)':''));out.push(lines.join('\n'))});
 return (flatName?'League Rosters'+flatName+'\n':'')+out.join('\n')}
function trEspnParse(txt,players){txt=trEspnFlat(txt);let idx={},L=txt.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),teams=[],miss=[];
 players.forEach(p=>(idx[trEspnKey(p.name)]=idx[trEspnKey(p.name)]||[]).push(p));
 L.forEach((l,i)=>{if(/^\(\d+-\d+(-\d+)?\)$/.test(l)&&i){let m=l.match(/(\d+)-(\d+)(?:-(\d+))?/);return teams.push({n:L[i-1],ids:[],w:+m[1],l:+m[2],t:+(m[3]||0),rec:m[1]+'-'+m[2]+(+(m[3]||0)?'-'+m[3]:''),i0:i})}
  let h=l.length/2,T=teams[teams.length-1],nm=L[i+1],sm=l.match(/^(QB|RB|WR|TE|FLEX|Bench|IR|K|D\/ST)\s+(\S.*)$/);
  if(!T)return;let pos;
  if(sm&&!/^Empty$/i.test(sm[2].trim())){nm=sm[2].trim();pos=L.slice(i+1,i+7).find(x=>/^(QB|RB|WR|TE|K|D\/ST)$/.test(x))}
  else{if(l.length%2||nm!==l.slice(0,h)||nm!==l.slice(h))return;pos=L.slice(i+2,i+6).find(x=>/^(QB|RB|WR|TE|K|D\/ST)$/.test(x))}
  if(pos==='K'||pos==='D/ST'){let r=pos==='K'?kdFindK(nm):kdFindD(nm);if(r&&T.ids.indexOf(r.id)<0)T.ids.push(r.id);else if(!r)miss.push(nm);return}
  let c=idx[trEspnKey(nm)]||[],p=c.find(x=>x.pos===pos)||c[0];if(p)T.ids.push(p.id);else miss.push(nm)});
 /* your own team is the one with no "Propose Trade" button */
 teams.forEach((T,k)=>{let end=k+1<teams.length?teams[k+1].i0-1:L.length;T.prop=L.slice(T.i0,end).some(x=>x.indexOf('Propose Trade')>=0)});
 let mine=teams.map((T,k)=>T.prop?-1:k).filter(k=>k>=0);
 return {teams,miss,me:mine.length===1?mine[0]:-1,set:trEspnSettings(L,teams),name:(function(){let x=L.find(y=>/^League Rosters\s*\S/.test(y));return x?x.replace(/^League Rosters\s*/,'').trim():''})()}}
/* ===== League (ESPN import), shared by Compare, My team analyzer and Trade ===== */
function lgOn(){return !TR.lgOff&&!!(TR.lg&&TR.lg.length)}
var LGIMP={add:true};
(function(){if((!TR.leagues||!TR.leagues.length)&&TR.lgAll&&TR.lgAll.length>1){TR.leagues=[{id:1,name:'My league',lgAll:JSON.parse(JSON.stringify(TR.lgAll)),lgMe:TR.lgMe,lgTs:TR.lgTs,st:JSON.parse(JSON.stringify(TR.st)),sf:TR.sf,n:TR.n}];TR.lgCur=0}})();
function lgSaveCur(){let l=TR.leagues&&TR.leagues[TR.lgCur];if(!l)return;l.lgAll=JSON.parse(JSON.stringify(TR.lgAll));l.lgMe=TR.lgMe;l.lgTs=TR.lgTs;l.st=JSON.parse(JSON.stringify(TR.st));l.sf=TR.sf;l.n=TR.n;l.espnPj=TR.espnPj||{};l.espnAdv=TR.espnAdv||null;trSave()}
function lgStore(name){let rec={id:Date.now(),name:(name||'').trim().slice(0,28)||'My league',lgAll:JSON.parse(JSON.stringify(TR.lgAll)),lgMe:TR.lgMe,lgTs:TR.lgTs,st:JSON.parse(JSON.stringify(TR.st)),sf:TR.sf,n:TR.n,espnPj:TR.espnPj||{},espnAdv:TR.espnAdv||null};TR.leagues=TR.leagues||[];if(!LGIMP.add&&TR.lgCur>=0&&TR.leagues[TR.lgCur]){rec.id=TR.leagues[TR.lgCur].id;if(!(name||'').trim())rec.name=TR.leagues[TR.lgCur].name;TR.leagues[TR.lgCur]=rec}else{TR.leagues.push(rec);TR.lgCur=TR.leagues.length-1}TR.lgOff=false;trSave()}
function lgRefresh(){trSave();trRenderAll();try{tAutoMine();renderTeams()}catch(e){}}
function lgUseLeague(i){let l=TR.leagues[i];if(!l)return;TR.espnPj=l.espnPj||{};TR.espnAdv=l.espnAdv||null;TR.lgCur=i;TR.lgOff=false;TR.st=JSON.parse(JSON.stringify(l.st||TR.st));TR.sf=!!l.sf;TR.n=l.n||TR.n;TRC=null;lgApply(JSON.parse(JSON.stringify(l.lgAll)),l.lgMe,false);TR.lgTs=l.lgTs||0;trSave();trRenderAll()}
function lgNameModal(title,val,ok,delMsg){let m=document.createElement('div');m.className='trModal';m.innerHTML=delMsg?`<div class="trModalB"><b>${title}</b><p>${delMsg}</p><div class="lgTb"><button type="button" class="trAsk lgOk">Delete</button><button type="button" class="trAsk lgX">Cancel</button></div></div>`:`<div class="trModalB"><b>${title}</b><input class="lgNmI" maxlength="28" value="${trEsc(val||'')}"><div class="lgTb"><button type="button" class="trAsk lgOk">Save</button><button type="button" class="trAsk lgX">Cancel</button></div></div>`;m.onclick=e=>{if(e.target===m||e.target.classList.contains('lgX'))m.remove();else if(e.target.classList.contains('lgOk')){let v=m.querySelector('.lgNmI');ok(v?v.value:'');m.remove()}};document.body.appendChild(m);let i=m.querySelector('.lgNmI');if(i){i.focus();i.select()}}
document.addEventListener('change',e=>{let t=e.target;if(!t.classList||!t.classList.contains('lgLs'))return;if(t.value==='off'){TR.lgOff=true;trLgOffClear();lgRefresh()}else lgUseLeague(+t.value)});
document.addEventListener('click',e=>{let t=e.target.closest&&e.target.closest('.lgRn,.lgDel');if(!t)return;let l=TR.leagues&&TR.leagues[TR.lgCur];if(!l)return;if(t.classList.contains('lgRn'))lgNameModal('Rename league',l.name,v=>{l.name=(v||'').trim().slice(0,28)||l.name;lgRefresh()});else lgNameModal('Delete league','',()=>{TR.leagues.splice(TR.lgCur,1);if(TR.leagues.length)lgUseLeague(0);else{TR.lgCur=-1;TR.lg=[];TR.lgAll=[];TR.lgMe=-1;TR.lgi=-1;TR.lgOff=false;lgRefresh()}},'This removes "'+trEsc(l.name)+'" from this device. You can import it again any time.')});
function lgOwned(){let m={};(TR.lg||[]).forEach(t=>t.ids.forEach(i=>m[i]=t.n));return m}
function lgAllIds(){let st=new Set(TR.my);(TR.lg||[]).forEach(t=>t.ids.forEach(i=>st.add(i)));if(TR.lgi<0)TR.their.forEach(i=>st.add(i));return st}
function lgApply(all,me,fresh){TR.lgAll=all.map(t=>({n:t.n,ids:t.ids.slice(),rec:t.rec||'',w:t.w,l:t.l,t:t.t,seed:t.seed||0,pf:t.pf||0,pa:t.pa||0}));TR.lgMe=me;if(fresh)TR.lgTs=Date.now();let m=all[me],oth=all.filter((t,i)=>i!==me).map(t=>({n:t.n,ids:t.ids.slice()}));
 TR.my=m.ids.slice();TR.tname=m.n.slice(0,22);TR.lg=oth;TR.lgi=oth.length?0:-1;TR.their=oth.length?oth[0].ids.slice():[];TR.send={my:[],their:[]};TR.give=[];TR.get=[];TR.inc=[];TR.n=Math.max(6,Math.min(20,all.length));TRIC=null;
 trSave();trRenderAll();try{tAutoMine();renderTeams()}catch(e){}}
function trEspnWhy(txt,r){let t=(txt||'').trim();if(!t)return 'The box is empty. Paste the Rosters page you copied from ESPN.';
 if(/^\s*(\{|\[)/.test(t))return 'That looks like code, not the page. Click on the page, press Ctrl+A (Cmd+A on a Mac), then copy.';
 if(t.length<400)return 'That is too short to be the whole Rosters page. Click on the page, select all, and copy again.';
 if(/yahoo\.com|sleeper\.(app|com)/i.test(t)&&!/espn/i.test(t))return 'This only reads ESPN right now. Yahoo and Sleeper are not supported yet.';
 let hasRec=/\(\d+-\d+(-\d+)?\)/.test(t),nTeams=r.teams.length,got=r.teams.reduce((s,x)=>s+x.ids.length,0);
 if(!hasRec&&/espn/i.test(t))return 'We only found the ESPN menu, not the teams. Wait until every team’s player list is showing on the Rosters page (scroll down once so it loads), then select all and copy again.';
 if(!hasRec)return 'We could not find any teams. Open League › Rosters on ESPN, select the whole page, and copy it.';
 if(nTeams===1)return 'We found only one team. Copy the League › Rosters page (it shows every team), not a single team’s page.';
 if(nTeams<2)return 'We could not find teams in that. Make sure you are on League › Rosters, then select all and copy.';
 if(got<nTeams*3)return 'We found '+nTeams+' teams but almost no players in them. The page may not have finished loading. Wait for the rosters to appear, then copy again.';
 return ''}
function lgPickBody(m,all,det,miss,set,nm){let B=m.querySelector('.trModalB'),dflt=(nm!==undefined)?(nm||(!LGIMP.add&&TR.leagues&&TR.leagues[TR.lgCur]?TR.leagues[TR.lgCur].name:'League '+((TR.leagues||[]).length+1))):'';
 B.innerHTML=`<b>Which team is yours?</b>${nm!==undefined?`<label class="lgNmL">League name <input class="lgNmI" maxlength="28" value="${trEsc(dflt)}"></label>`:''}<p>Tap your team.${det>=0?' We highlighted the one we think it is, because ESPN shows no Propose Trade button on your own team.':''}</p><div class="lgPick">${all.map((t,i)=>`<button type="button" class="lgPk${i===det?' det':''}" data-i="${i}"><b>${trEsc(t.n)}</b><small>${t.rec?t.rec+' • ':''}${t.ids.length} players${i===det?' • looks like yours':''}</small></button>`).join('')}</div>`;
 B.querySelectorAll('.lgPk').forEach(b=>b.onclick=()=>{let i=+b.dataset.i,ni=B.querySelector('.lgNmI');lgApply(all,i,nm!==undefined);let sm='';if(set){TR.st={QB:set.QB,RB:set.RB,WR:set.WR,TE:set.TE,FLEX:set.FLEX,K:set.K?1:0,DST:set.DST?1:0};TR.sf=set.sf;TR.n=Math.max(6,Math.min(20,set.n));TRC=null;trSave();try{trRenderAll()}catch(e){};sm=` Settings read from your page: ${set.n} teams, ${set.QB} QB, ${set.RB} RB, ${set.WR} WR, ${set.TE} TE, ${set.FLEX} ${set.sf?'superflex':'flex'}, ${set.bench} bench.`}if(nm!==undefined)lgStore(ni?ni.value:'');else lgSaveCur();m.remove();trNotice('League saved',`<b>${trEsc(all[i].n)}</b> is your team.${sm} The other ${all.length-1} teams are saved as trade partners and for comparing.${miss&&miss.length?` Not in our player pool, so left out: ${miss.map(trEsc).join(', ')}.`:''} Kickers and defenses were skipped.`)})}
function lgChange(){if(!TR.lgAll||TR.lgAll.length<2)return trEspnModal();let m=document.createElement('div');m.className='trModal';m.innerHTML='<div class="trModalB"></div>';m.onclick=e=>{if(e.target===m)m.remove()};document.body.appendChild(m);lgPickBody(m,TR.lgAll,TR.lgMe,[])}
