function lgStand(){let kd=kdAdd(),wk=META.next_week,all=[{n:TR.tname||'Your team',ids:TR.my,me:true,i:-1}].concat(TR.lg.map((t,i)=>({n:t.n,ids:t.ids,i,t}))),
 rows=all.map(t=>{let L=trLineup(t.ids,'later'),pace=L.st.reduce((s,x)=>s+(x.v&&x.v.p.m&&x.v.p.m.ppr!=null?+x.v.p.m.ppr:0),0)+kdAdd(t.ids,'ppg'),rc=lgRecOf(t.t||{n:t.n},t.me);return {n:t.n,me:t.me,i:t.i,w:rc?rc.w:null,l:rc?rc.l:null,tt:rc?rc.t:0,pace,wkp:trLineupWD(t.ids,wk).tot+kdAdd(t.ids,wk)}}),
 hasRec=rows.every(r=>r.w!=null),pct=r=>(r.w+(r.tt||0)/2)/Math.max(1,r.w+r.l+(r.tt||0));
 rows.sort((a,b)=>hasRec?(pct(b)-pct(a)||b.pace-a.pace):b.pace-a.pace);
 let rk=(f)=>{let o=rows.slice().sort((a,b)=>f(b)-f(a)),m={};o.forEach((r,i)=>m[r.n]=i+1);return m};
 return {rows,hasRec,rkPace:rk(r=>r.pace),rkWk:rk(r=>r.wkp)}}
