 let qb=posS('QB')[0];if(qb){let mate=starters.find(v=>v.p!==qb.p&&(v.p.pos==='WR'||v.p.pos==='TE')&&v.p.team===qb.p.team);if(mate)add('stack','QB Stack',64,`${bold(ln(qb.p))} and ${bold(ln(mate.p))} both play for ${bold(qb.p.team)}. When that offense scores, you score twice.`)}
 let tc={};starters.forEach(v=>tc[v.p.team]=(tc[v.p.team]||0)+1);let tk=Object.keys(tc).sort((a,b)=>tc[b]-tc[a])[0];if(tk&&tc[tk]>=3)add('stack','One-Team Stack',66,`${bold(tc[tk])} starters play for ${bold(tk)}. Their bye week will hurt.`);
 /* byes */
