  let shown=D.all.slice(0,TRI.n);
  h+=shown.length?shown.map(d=>`<div class="trDeal"><div class="trDealT"><span><b>Send</b> ${d.A.map(x=>`${trL(x.p)} <i>${x.p.pos}</i>`).join(' + ')}</span><span><b>Get</b> ${trL(d.T.p)} <i>${d.T.p.pos} ${trN(d.T.val)}</i>${d.own?' <i>on '+trEsc(d.own)+'</i>':''}${d.T.pl.R>0?' <i class="trTag bad">'+(d.T.pl.label||'Out')+'</i>':''}</span></div><div class="trDealM">${d.pp} help • ${Math.abs(d.gap)<.04?'Even on value':d.gap>0?'Slightly in your favor on value':'Slightly in theirs on value'} • lineup <b class="up">${trWord(d.d)}</b>${Math.abs(d.n1)>=.2?` • ${trWord(d.n1).toLowerCase()} over the next 4 weeks`:''}</div><button type="button" class="trAsk trIdea" data-a="${d.A.map(x=>x.p.id).join(',')}" data-t="${d.T.p.id}">Test in Quick trade</button></div>`).join(''):'<p class="tnote">No fair package from your bench clearly helps here. Try another position, or pair a starter you can spare.</p>';
