function trAb(n){let a=n.split(' ');return a.length>1?a[0][0]+'. '+a.slice(1).join(' '):n}
function trLgMania(){let c=trCtx(),sum=0,wt=0;TRPOS.forEach(pos=>{let k=Math.max(1,Math.round(TR.n*c.S[pos])),a=c.vs.filter(v=>v.p.pos===pos&&!v.pl.gone&&v.p.mania!=null).map(v=>+v.p.mania).sort((x,y)=>y-x).slice(0,k);if(a.length){sum+=c.S[pos]*a.reduce((s,x)=>s+x,0)/a.length;wt+=c.S[pos]}});return wt?sum/wt:null}
