 ctl=`<div class="shCtl">${seg('mode',TRSH.mode,[['all','Overall'],['week','Week '+w]])}${wk?'':seg('metric',TRSH.metric,[['mania','Mania Rating'],['pts','Avg points']])}<div class="shCtlR"><button type="button" class="shB shT${kd?' on':''}" data-k="kd">${ICO.k}${ICO.d} K + DEF</button><button type="button" class="shB shT" data-k="reset">Reset</button><button type="button" class="shB shT${TRSH.noType?' on':''}" data-k="noType">Team type</button><button type="button" class="shB shT" data-k="hide">Hide buttons</button><button type="button" class="shB shT shXb" data-k="close" aria-label="Close">✕</button></div></div>`,
 pick=s=>{let opts=M.V.filter(v=>trElig(s.slot,v.p.pos)&&(!M.seen.has(v.p.id)||(s.v&&s.v.p.id===v.p.id))).sort((x,y)=>(trShotVal(y,w)||-1)-(trShotVal(x,w)||-1));return `<div class="shPick"><small>Swap in a ${trSlotLab(s.slot)}</small>${opts.map(v=>{let x=trShotVal(v,w);return `<button type="button" class="shO${s.v&&s.v.p.id===v.p.id?' cur':''}" data-i="${s.i}" data-id="${v.p.id}"><b>${v.p.name}</b><span>${v.p.pos} • ${v.p.team}${wk&&x==null?' • '+(v.gw.indexOf(w)<0?'bye':'out'):''}</span><em>${x==null?'—':x.toFixed(1)}</em></button>`}).join('')||'<span class="shNone">No one else fits this spot</span>'}</div>`},
 rows=M.slots.map(s=>{let p=s.v&&s.v.p,op=p&&oppOf(p.team,w),vv=s.val,tag=wk&&s.v&&vv==null?(s.v.gw.indexOf(w)<0?'Bye':'Out'):'';
  return (p?`<button type="button" class="shR${s.sw?' sw':''}${TRSH.edit===s.i?' open':''}" data-i="${s.i}"><span class="shS p${s.slot.replace('SFLEX','FLEX')}">${trSlotLab(s.slot)}</span>${thumb(p)}<span class="shN"><b>${trAb(p.name)}</b><small>${p.team} • ${p.pos}${op?' • vs '+op:''}</small></span><span class="shP">${tag?`<i>${tag}</i>`:(mania&&!wk?f1(vv):f1(vv))}</span></button>`:`<button type="button" class="shR" data-i="${s.i}"><span class="shS p${s.slot.replace('SFLEX','FLEX')}">${trSlotLab(s.slot)}</span><span></span><span class="shN"><b>Empty</b><small>tap to add</small></span><span class="shP">—</span></button>`)+(TRSH.edit===s.i?pick(s):'')}).join(''),
