document.addEventListener('change',e=>{let t=e.target;if(t.classList&&t.classList.contains('kdC')){KD.on=t.checked;kdSave();kdRe();return}if(t.classList&&t.classList.contains('kdI')){KD[t.dataset.k]=Math.max(0,Math.min(30,+t.value||0));kdSave();kdRe()}});
