function kdPc(r,f,low){var L=(r.pos==='K'?KDX.k:KDX.d)||[],me=f(r);if(me==null||isNaN(me))return null;var a=L.filter(function(x){var v=f(x);return v!=null&&!isNaN(v)});if(a.length<2)return null;var w=a.filter(function(x){var v=f(x);return low?v>me:v<me}).length,t=a.filter(function(x){var v=f(x);return v===me}).length;return Math.max(1,Math.min(99,Math.round(100*(w+Math.max(0,t-1)/2)/(a.length-1))))}
function kdSd(r){var L=(r.log||[]).map(function(l){return l.pts});if(L.length<3)return null;var m=L.reduce(function(a,b){return a+b},0)/L.length;return Math.sqrt(L.reduce(function(a,b){return a+(b-m)*(b-m)},0)/L.length)}
