/* one true Mania Rating: the official number (hurt game left out) is the anchor; ticking games only moves it from there */
var _calcRaw=calc;calc=function(p,idxs){var c=_calcRaw(p,idxs);if(!c||window.RAWC||sameSet(idxs,dfl(p)))return c;window.RAWC=1;var d;try{d=_calcRaw(p,dfl(p))}finally{window.RAWC=0}if(!d)return c;var adj=p.mania-d.mania;c.mania=Math.max(0,Math.min(99.5,c.mania+adj));if(!(p.out||p.played)&&p.start!=null)c.start=Math.max(0,Math.min(100,c.start+adj));return c};

function ageOf(p){if(!p||!p.born)return null;var b=new Date(p.born+'T12:00:00');if(isNaN(b))return null;var n=new Date(),a=n.getFullYear()-b.getFullYear();if(n.getMonth()<b.getMonth()||(n.getMonth()===b.getMonth()&&n.getDate()<b.getDate()))a--;return a>=18&&a<50?a:null}

