function cxBBst(p){var L=cxLogs(p).map(function(l){return +l.ppr}),n=L.length;if(!n)return null;var mu=L.reduce(function(s,x){return s+x},0)/n,sd=Math.sqrt(L.reduce(function(s,x){return s+(x-mu)*(x-mu)},0)/n),s=L.slice().sort(function(a,b){return a-b}),med=n%2?s[(n-1)/2]:(s[n/2-1]+s[n/2])/2,cv=mu>0?sd/mu:null,boom=L.filter(function(x){return x>=mu*1.4&&x>=mu+4}).length,bust=L.filter(function(x){return x<=mu*.5}).length,hit=L.filter(function(x){return x>=mu*.8}).length/n;return {L:L,n:n,mu:mu,sd:sd,med:med,best:s[n-1],worst:s[0],cv:cv,boom:boom,bust:bust,hit:hit,lab:n<3?'Small sample':cv<.45?'Steady':cv<.75?'Some swings':'Boom or bust'}}
